package com.hbm.machine.excavator;
import com.hbm.item.battery.*;import com.hbm.item.fluid.FluidIdentifier;import com.hbm.block.ore.DrillbitItem;import net.minecraft.core.BlockPos;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.world.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.*;import net.minecraft.world.item.ItemStack;
public final class ExcavatorMenu extends AbstractContainerMenu {
 private final Container machine;private final BlockPos pos;
 public ExcavatorMenu(int id,Inventory inv,RegistryFriendlyByteBuf buffer){this(id,inv,resolve(inv,buffer));}private ExcavatorMenu(int id,Inventory inv,Init init){this(id,inv,init.machine,init.pos);}private record Init(Container machine,BlockPos pos){}private static Init resolve(Inventory inv,RegistryFriendlyByteBuf buffer){var p=buffer.readBlockPos();return new Init(inv.player.level().getBlockEntity(p) instanceof ExcavatorBlockEntity machine?machine:new SimpleContainer(14),p);}
 public ExcavatorMenu(int id,Inventory inv,Container machine,BlockPos pos){super(ExcavatorContent.MENU.get(),id);this.machine=machine;this.pos=pos;addSlot(new Slot(machine,0,220,72));addSlot(new Slot(machine,1,202,72));for(int i=0;i<3;i++)addSlot(new Slot(machine,2+i,136+i*18,75));for(int i=0;i<3;i++)for(int j=0;j<3;j++)addSlot(output(machine,5+j+i*3,136+j*18,5+i*18));for(int i=0;i<3;i++)for(int j=0;j<9;j++)addSlot(new Slot(inv,j+i*9+9,41+j*18,122+i*18));for(int j=0;j<9;j++)addSlot(new Slot(inv,j,41+j*18,180));}
 private static Slot output(Container c,int i,int x,int y){return new Slot(c,i,x,y){@Override public boolean mayPlace(ItemStack stack){return false;}};}public BlockPos position(){return pos;}@Override public boolean stillValid(Player player){return machine.stillValid(player);}
 @Override public ItemStack quickMoveStack(Player player,int index){var slot=slots.get(index);if(!slot.hasItem())return ItemStack.EMPTY;var stack=slot.getItem();var copy=stack.copy();if(index<=13){if(!moveItemStackTo(stack,14,slots.size(),true))return ItemStack.EMPTY;}else{int first,last;var item=stack.getItem();if(item instanceof HbmBattery||item instanceof CreativeBatteryItem){first=0;last=1;}else if(item instanceof FluidIdentifier){first=1;last=2;}else if(item instanceof com.hbm.machine.electricfurnace.FurnaceUpgradeItem||item instanceof com.hbm.machine.crystallizer.EffectUpgradeItem||item instanceof com.hbm.machine.centrifuge.OverdriveUpgradeItem){first=2;last=4;}else if(item instanceof DrillbitItem){first=4;last=5;}else return ItemStack.EMPTY;if(!moveItemStackTo(stack,first,last,false))return ItemStack.EMPTY;}if(stack.isEmpty())slot.set(ItemStack.EMPTY);else slot.setChanged();return copy;}
}
